// Where Ziffr runs, without a trailing slash.
const ZIFFR_URL = 'https://ziffr.example.com';

// The caller is untrusted: check shapes and sizes here, so a bad call never reaches Ziffr. Ziffr checks again.
const SLUG = /^[a-z0-9][a-z0-9-]{0,99}$/;
const DAY = /^\d{4}-\d{2}-\d{2}$/;
const req = $input.first().json;
const body = req.body ?? {};
const raw = Array.isArray(body.items) ? body.items : [body];
const fail = (error) => [{ json: { ok: false, error } }];

if (raw.length < 1 || raw.length > 500) return fail('Send 1 to 500 items.');
const num = (v) => (typeof v === 'string' && v.trim() !== '' ? Number(v) : v);
const items = [];
for (const [i, it] of raw.entries()) {
  if (!it || typeof it !== 'object') return fail(`Item ${i}: not an object.`);
  const metric = String(it.metric ?? '');
  if (!SLUG.test(metric)) return fail(`Item ${i}: metric must be a Metric slug, such as sign-ups.`);
  const value = num(it.value);
  if (typeof value !== 'number' || !Number.isFinite(value)) return fail(`Item ${i}: value must be a number.`);
  const out = { metric, value };
  if (it.period != null) {
    if (!DAY.test(String(it.period)) || Number.isNaN(Date.parse(it.period))) return fail(`Item ${i}: period must be a date, YYYY-MM-DD.`);
    out.period = String(it.period);
  }
  if (it.breakdown != null) {
    if (!Array.isArray(it.breakdown) || it.breakdown.length > 500) return fail(`Item ${i}: breakdown must be a list of at most 500 rows.`);
    out.breakdown = [];
    for (const row of it.breakdown) {
      const label = String(row?.label ?? '').trim();
      const v = num(row?.value);
      if (!label || label.length > 200 || typeof v !== 'number' || !Number.isFinite(v)) return fail(`Item ${i}: each breakdown row needs a label (1 to 200 characters) and a number.`);
      out.breakdown.push({ label, value: v });
    }
  }
  items.push(out);
}

const idem = String(req.headers?.['idempotency-key'] ?? '');
if (idem && !/^[\x21-\x7e]{1,200}$/.test(idem)) return fail('Idempotency-Key: 1 to 200 visible ASCII characters.');
return [{ json: { ok: true, url: `${ZIFFR_URL}/api/v1/feed/observations`, idempotencyKey: idem, payload: { items } } }];
